"""Compliance post-processor (PRD §10.5) and the number-tracing check (§10.6).

The model's raw output is kept verbatim in the API transcript; only the text shown to
the investor is processed here.
"""

import json
import re

DISCLOSURE_TEXT = {
    "mf_market_risk": "Mutual Fund investments are subject to market risks, read all scheme related documents carefully. Past performance may or may not be sustained in future.",
    "ai_generated": "Generated by RA, an AI guide. It can make mistakes; a human expert can review any suggestion on request.",
}

_NEGATED = re.compile(r"\b(not|no|never|isn't|aren't|don't|doesn't|cannot|can't|nothing|neither|nor|without)\b[^.!?]{0,40}$", re.I)

RULES: list[tuple[str, re.Pattern, str]] = [
    ("guarantee_claim", re.compile(r"\b(guaranteed|assured)\s+(returns?|income|profits?|gains?)\b", re.I), "high"),
    ("risk_free_claim", re.compile(r"\brisk[- ]free\b", re.I), "high"),
    ("free_review_claim", re.compile(r"\bfree (portfolio )?review\b", re.I), "medium"),
    ("adviser_claim", re.compile(r"\b(i am|i'm|as)\s+(your\s+|an?\s+)?(investment\s+|financial\s+)?advis[eo]r\b", re.I), "high"),
    ("planning_term", re.compile(r"\bfinancial plann(ing|er)\b", re.I), "low"),
    ("advisory_term", re.compile(r"\badvisory\b", re.I), "low"),
]

CORRECTIONS = {
    "guarantee_claim": "To be clear: mutual fund returns are not guaranteed, and every fund carries risk.",
    "risk_free_claim": "To be clear: mutual fund returns are not guaranteed, and every fund carries risk.",
    "adviser_claim": "Note: RA is an AI guide working under an AMFI-registered Mutual Fund Distributor, not an investment adviser.",
    "free_review_claim": None,
}

DATA_TOOLS = {"fund_lens", "compare_funds"}


def check_text(text: str) -> list[dict]:
    flags = []
    for code, pattern, severity in RULES:
        for m in pattern.finditer(text):
            before = text[max(0, m.start() - 60): m.start()]
            if _NEGATED.search(before):
                continue
            flags.append({"code": code, "severity": severity, "match": m.group(0)})
    return flags


def post_process(text: str, tools_used: set[str]) -> tuple[str, list[dict], list[str]]:
    flags = check_text(text)
    corrections = []
    for f in flags:
        note = CORRECTIONS.get(f["code"])
        if note and note not in corrections:
            corrections.append(note)
    display = text.rstrip()
    if corrections:
        display += "\n\n" + " ".join(corrections)

    disclosures = []
    if tools_used & DATA_TOOLS or re.search(r"\d+(\.\d+)?\s*%", text):
        disclosures.append("mf_market_risk")
    if tools_used:
        disclosures.append("ai_generated")
    return display, flags, disclosures


# --------------------------------------------------------------------------- number tracing

_NUM = re.compile(r"(₹\s?)?(-?\d[\d,]*(?:\.\d+)?)\s*(%|lakh|lakhs|lac|crore|cr|k)?", re.I)
_MULT = {"lakh": 1e5, "lakhs": 1e5, "lac": 1e5, "crore": 1e7, "cr": 1e7, "k": 1e3}


def untraced_numbers(answer: str, sources: list[str]) -> list[str]:
    """Numbers in `answer` that no tool output / user text supports.

    Each answer number becomes its exact value (₹12.5 lakh -> 1,250,000) and must sit within
    half a unit of its displayed precision of some source number (so ₹12.5 lakh covers
    1,245,000-1,255,000). Percentages may also match a source fraction x100. Small bare
    integers (counts, days) and years are ignored.
    """
    src = []
    for s in sources:
        for m in re.finditer(r"-?\d+(?:\.\d+)?", s.replace(",", "")):
            src.append(abs(float(m.group(0))))
    missing = []
    for m in _NUM.finditer(answer):
        rupee, raw, unit = m.group(1), m.group(2), (m.group(3) or "").lower()
        num = raw.replace(",", "").lstrip("-")
        try:
            val = float(num)
        except ValueError:
            continue
        if not (rupee or unit) and "." not in num and (val < 1000 or 1900 <= val <= 2100):
            continue
        mult = _MULT.get(unit, 1.0)
        decimals = len(num.split(".")[1]) if "." in num else 0
        target, tol = val * mult, (10 ** -decimals) * mult / 2 + 1e-9
        candidates = src + [x * 100 for x in src] if unit == "%" else src
        if not any(abs(x - target) <= tol for x in candidates):
            missing.append(m.group(0).strip())
    return missing


def sources_from_tool_calls(tool_calls: list[dict], user_text: str) -> list[str]:
    return [user_text] + [json.dumps(t.get("output"), default=str) for t in tool_calls]
